<?php require 'config.php';$pageTitle='Đăng nhập';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$password=$_POST['password']??'';$st=$pdo->prepare('SELECT * FROM users WHERE email=?');$st->execute([$email]);$u=$st->fetch();if($u&&password_verify($password,$u['password'])){session_regenerate_id(true);$_SESSION['user']=['user_id'=>$u['user_id'],'full_name'=>$u['full_name'],'email'=>$u['email'],'role'=>$u['role']];header('Location: '.($u['role']==='admin'?'admin/index.php':'index.php'));exit;}else $error='Email hoặc mật khẩu không chính xác.';}require 'includes/header.php';?><div class="row justify-content-center"><div class="col-md-5"><form method="post" class="content-card"><h1 class="section-title">Đăng nhập</h1><?php if(isset($_GET['registered'])): ?><div class="alert alert-success">Đăng ký thành công. Hãy đăng nhập.</div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="mb-3"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><div class="mb-3"><label class="form-label">Mật khẩu</label><input class="form-control" type="password" name="password" required></div><button class="btn btn-red">Đăng nhập</button><p class="mt-3 mb-0">Chưa có tài khoản? <a href="register.php">Đăng ký</a></p></form></div></div><?php require 'includes/footer.php';?>
